def vibe_check(workspace_id, session_id, input_text, context=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0363000" if __import__("os").path.isdir("./environment_mix/0363000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _make_id(prefix):
        # deterministic enough for offline: time + random-ish hash
        raw = f"{time.time_ns()}:{os.getpid()}:{os.urandom(8).hex()}"
        token = hashlib.sha1(raw.encode("utf-8")).hexdigest().upper()[:12]
        return f"{prefix}{token}"

    def _estimate_tokens(text):
        # cheap heuristic: ~4 chars/token, at least 1 if text present
        if text is None:
            return None
        if not isinstance(text, str):
            return None
        t = max(1, (len(text) + 3) // 4) if text else 0
        return t

    t0 = time.time()

    # ---- validation (types/patterns) ----
    if not isinstance(workspace_id, str) or not re.match(r"^vbc_wsp_[0-9A-Z]+$", workspace_id or ""):
        return _err("VALIDATION_ERROR", "workspace_id must match ^vbc_wsp_[0-9A-Z]+$")
    if not isinstance(session_id, str) or not re.match(r"^vbc_sess_[0-9A-Z]+$", session_id or ""):
        return _err("VALIDATION_ERROR", "session_id must match ^vbc_sess_[0-9A-Z]+$")
    if not isinstance(input_text, str):
        return _err("VALIDATION_ERROR", "input_text must be a string")
    if input_text.strip() == "":
        return _err("VALIDATION_ERROR", "input_text must not be empty")
    if context is not None and not isinstance(context, dict):
        return _err("VALIDATION_ERROR", "context must be an object when provided")

    # ---- load store ----
    workspaces = _load("workspaces.json")
    sessions = _load("sessions.json")
    tool_runs = _load("tool_runs.json")
    learned_patterns = _load("learned_patterns.json")

    # ---- auth (ambient): pick a workspace/session combination that satisfies prerequisites ----
    wsp = next((w for w in workspaces if w.get("id") == workspace_id and w.get("status") == "active"), None)
    if not wsp:
        # treat missing or non-active as unauthorized per "authorized to read; refuses if lacks access"
        return _err("UNAUTHORIZED", "Not authorized for workspace, or workspace not active")

    sess = next((s for s in sessions if s.get("id") == session_id and s.get("workspace_id") == workspace_id), None)
    if not sess:
        return _err("NOT_FOUND", "Session not found in workspace")
    if sess.get("status") == "deleted":
        return _err("INVALID_TRANSITION", "Cannot run tools on a deleted session")

    # ---- create tool_run row (exactly one per call) ----
    now = _now()
    run_id = _make_id("vbc_run_")
    req_payload = {"workspace_id": workspace_id, "session_id": session_id, "input_text": input_text}
    if context is not None:
        req_payload["context"] = context

    run_row = {
        "id": run_id,
        "workspace_id": workspace_id,
        "session_id": session_id,
        "tool_name": "vibe_check",
        "status": "running",
        "request_payload": req_payload if isinstance(req_payload, dict) else {},
        "input_text": input_text,
        "response_payload": None,
        "output_text": None,
        "error_code": None,
        "error_message": None,
        "duration_ms": None,
        "tokens_in": _estimate_tokens(input_text),
        "tokens_out": None,
        "created_at": now,
        "updated_at": now,
        "started_at": now,
        "finished_at": None,
    }
    tool_runs.append(run_row)

    # ---- optionally persist session context (store on session) ----
    if context is not None:
        # merge shallowly into session.context (object)
        if sess.get("context") is None or not isinstance(sess.get("context"), dict):
            sess["context"] = {}
        for k, v in context.items():
            sess["context"][k] = v
        sess["updated_at"] = now

    # ---- analysis: read active learned_patterns in same workspace (no modifications) ----
    text_l = input_text.lower()
    active_patterns = [p for p in learned_patterns if p.get("workspace_id") == workspace_id and p.get("status") == "active"]
    warnings = []
    # simple relevance heuristic: keyword overlap with title/problem/tags
    for p in active_patterns:
        title = (p.get("title") or "")
        problem = (p.get("problem") or "")
        tags = p.get("tags") if isinstance(p.get("tags"), list) else []
        blob = " ".join([title, problem, " ".join([str(t) for t in tags])]).lower()
        if not blob.strip():
            continue
        # token-based match: any word length>=4 present
        matched_terms = []
        for term in set(re.findall(r"[a-z0-9_\-]{4,}", blob)):
            if term in text_l:
                matched_terms.append(term)
        if matched_terms:
            warnings.append(
                {
                    "pattern_id": p.get("id"),
                    "pattern_key": p.get("pattern_key"),
                    "title": title,
                    "matched_terms": sorted(matched_terms)[:20],
                    "problem": p.get("problem"),
                    "solution": p.get("solution"),
                    "tags": tags,
                    "evidence_count": p.get("evidence_count"),
                }
            )

    # Additional generic checks
    generic_flags = []
    if len(input_text) > 8000:
        generic_flags.append({"code": "LONG_INPUT", "message": "Input is long; consider summarizing or distilling."})
    if re.search(r"\b(todo|tbd|fixme)\b", text_l):
        generic_flags.append({"code": "UNRESOLVED_MARKERS", "message": "Found TODO/TBD/FIXME markers."})
    if "optimiz" in text_l or "premature" in text_l:
        generic_flags.append({"code": "POSSIBLE_PREMATURE_OPTIMIZATION", "message": "Mentions optimization; ensure correctness first."})

    analysis = {
        "warnings": warnings,
        "generic_flags": generic_flags,
        "summary": {
            "relevant_patterns": len(warnings),
            "active_patterns_scanned": len(active_patterns),
        },
    }
    output_text = f"Vibe check: {len(warnings)} relevant pattern warning(s), {len(generic_flags)} generic flag(s)."

    # ---- finalize tool_run ----
    finished = _now()
    run_row["status"] = "succeeded"
    run_row["response_payload"] = analysis
    run_row["output_text"] = output_text
    run_row["finished_at"] = finished
    run_row["updated_at"] = finished
    dur = int((time.time() - t0) * 1000)
    run_row["duration_ms"] = max(0, dur)
    # rough tokens_out: serialized response size / 4
    run_row["tokens_out"] = _estimate_tokens(json.dumps(analysis, ensure_ascii=False))

    # ---- persist ----
    _save("tool_runs.json", tool_runs)
    _save("sessions.json", sessions)

    return {"tool_run": run_row}

def vibe_distill(workspace_id, session_id, input_text, notes=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0363000" if __import__("os").path.isdir("./environment_mix/0363000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _make_id(prefix):
        raw = f"{time.time_ns()}:{os.getpid()}:{os.urandom(8).hex()}"
        token = hashlib.sha1(raw.encode("utf-8")).hexdigest().upper()[:12]
        return f"{prefix}{token}"

    def _estimate_tokens(text):
        if text is None:
            return None
        if not isinstance(text, str):
            return None
        return max(1, (len(text) + 3) // 4) if text else 0

    t0 = time.time()

    if not isinstance(workspace_id, str) or not re.match(r"^vbc_wsp_[0-9A-Z]+$", workspace_id or ""):
        return _err("VALIDATION_ERROR", "workspace_id must match ^vbc_wsp_[0-9A-Z]+$")
    if not isinstance(session_id, str) or not re.match(r"^vbc_sess_[0-9A-Z]+$", session_id or ""):
        return _err("VALIDATION_ERROR", "session_id must match ^vbc_sess_[0-9A-Z]+$")
    if not isinstance(input_text, str) or input_text.strip() == "":
        return _err("VALIDATION_ERROR", "input_text must be a non-empty string")
    if notes is not None and not isinstance(notes, str):
        return _err("VALIDATION_ERROR", "notes must be a string when provided")

    workspaces = _load("workspaces.json")
    sessions = _load("sessions.json")
    tool_runs = _load("tool_runs.json")
    distilled_plans = _load("distilled_plans.json")

    wsp = next((w for w in workspaces if w.get("id") == workspace_id and w.get("status") == "active"), None)
    if not wsp:
        return _err("UNAUTHORIZED", "Not authorized for workspace, or workspace not active")

    sess = next((s for s in sessions if s.get("id") == session_id and s.get("workspace_id") == workspace_id), None)
    if not sess:
        return _err("NOT_FOUND", "Session not found in workspace")
    if sess.get("status") == "deleted":
        return _err("INVALID_TRANSITION", "Cannot run tools on a deleted session")

    # create tool run
    now = _now()
    run_id = _make_id("vbc_run_")
    req_payload = {"workspace_id": workspace_id, "session_id": session_id, "input_text": input_text}
    if notes is not None:
        req_payload["notes"] = notes

    run_row = {
        "id": run_id,
        "workspace_id": workspace_id,
        "session_id": session_id,
        "tool_name": "vibe_distill",
        "status": "running",
        "request_payload": req_payload,
        "input_text": input_text,
        "response_payload": None,
        "output_text": None,
        "error_code": None,
        "error_message": None,
        "duration_ms": None,
        "tokens_in": _estimate_tokens(input_text),
        "tokens_out": None,
        "created_at": now,
        "updated_at": now,
        "started_at": now,
        "finished_at": None,
    }
    tool_runs.append(run_row)

    # "distill" heuristic extraction
    lines = [ln.strip() for ln in input_text.splitlines()]
    nonempty = [ln for ln in lines if ln]
    essential = []
    complexity = []
    simplifications = []

    for ln in nonempty:
        lnl = ln.lower()
        if re.match(r"^(\-|\*|\d+\.)\s+", ln):
            essential.append(re.sub(r"^(\-|\*|\d+\.)\s+", "", ln).strip())
        if any(k in lnl for k in ["microservice", "kubernetes", "event-sourcing", "cqrs", "blockchain", "ai", "ml", "over-engineer", "overengineer"]):
            complexity.append(ln)
        if any(k in lnl for k in ["should", "could", "maybe", "consider", "optional"]):
            simplifications.append(ln)

    if not essential:
        # fallback: first few sentences-ish
        chunks = re.split(r"[\.!\?]\s+", input_text.strip())
        essential = [c.strip() for c in chunks if c.strip()][:5]

    # simplify dedupe and cap sizes
    def _uniq(seq, maxn):
        seen = set()
        out = []
        for x in seq:
            if not isinstance(x, str):
                continue
            k = x.strip()
            if not k:
                continue
            if k.lower() in seen:
                continue
            seen.add(k.lower())
            out.append(k)
            if len(out) >= maxn:
                break
        return out

    essential = _uniq(essential, 20)
    complexity = _uniq(complexity, 15)
    simplifications = _uniq(
        simplifications
        + [
            "Start with a minimal end-to-end slice; defer scaling/optimization until after correctness is proven.",
            "Prefer a single service/module first; split only when you have clear boundaries and pain points.",
        ],
        15,
    )

    original_summary = None
    if len(nonempty) > 0:
        original_summary = nonempty[0][:240]

    plan_id = _make_id("vbc_plan_")

    # supersede existing active plan(s) in same session (application-level rule)
    updated_any = False
    finished = _now()
    for p in distilled_plans:
        if p.get("session_id") == session_id and p.get("workspace_id") == workspace_id and p.get("status") == "active":
            p["status"] = "superseded"
            p["updated_at"] = finished
            updated_any = True

    plan_row = {
        "id": plan_id,
        "workspace_id": workspace_id,
        "session_id": session_id,
        "source_run_id": run_id,
        "status": "active",
        "original_summary": original_summary,
        "essential_elements": essential if isinstance(essential, list) else [],
        "complexity_sources": complexity if isinstance(complexity, list) else [],
        "recommended_simplifications": simplifications if isinstance(simplifications, list) else [],
        "notes": notes,
        "created_at": finished,
        "updated_at": finished,
    }

    # unique(source_run_id)
    if any(p.get("source_run_id") == run_id for p in distilled_plans):
        # Shouldn't happen because run_id is new; still enforce.
        run_row["status"] = "failed"
        run_row["error_code"] = "CONFLICT_SOURCE_RUN"
        run_row["error_message"] = "A distilled plan already exists for this source_run_id"
        run_row["finished_at"] = finished
        run_row["updated_at"] = finished
        run_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        _save("tool_runs.json", tool_runs)
        return _err("CONFLICT", "A distilled plan already exists for this source_run_id")

    distilled_plans.append(plan_row)

    # finalize run (must be succeeded for plan creation rule; we created plan only after success path)
    run_row["status"] = "succeeded"
    run_row["response_payload"] = {"distilled_plan_id": plan_id, "superseded_previous_active": bool(updated_any)}
    run_row["output_text"] = f"Distilled plan created ({plan_id}). Essential elements: {len(essential)}."
    run_row["finished_at"] = finished
    run_row["updated_at"] = finished
    run_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
    run_row["tokens_out"] = _estimate_tokens(json.dumps(run_row["response_payload"], ensure_ascii=False))

    _save("tool_runs.json", tool_runs)
    _save("distilled_plans.json", distilled_plans)

    return {"tool_run": run_row, "distilled_plan": plan_row}

def vibe_learn(workspace_id, session_id, input_text, tags=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0363000" if __import__("os").path.isdir("./environment_mix/0363000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now():
        return _now_dt().isoformat()

    def _make_id(prefix):
        raw = f"{time.time_ns()}:{os.getpid()}:{os.urandom(8).hex()}"
        token = hashlib.sha1(raw.encode("utf-8")).hexdigest().upper()[:12]
        return f"{prefix}{token}"

    def _estimate_tokens(text):
        if text is None:
            return None
        if not isinstance(text, str):
            return None
        return max(1, (len(text) + 3) // 4) if text else 0

    def _norm_tags(t):
        if t is None:
            return []
        if not isinstance(t, list):
            return None
        out = []
        for x in t:
            if not isinstance(x, str):
                return None
            v = x.strip()
            if not v:
                continue
            out.append(v)
        # dedupe case-insensitive
        seen = set()
        ded = []
        for v in out:
            k = v.lower()
            if k in seen:
                continue
            seen.add(k)
            ded.append(v)
        return ded[:25]

    t0 = time.time()

    if not isinstance(workspace_id, str) or not re.match(r"^vbc_wsp_[0-9A-Z]+$", workspace_id or ""):
        return _err("VALIDATION_ERROR", "workspace_id must match ^vbc_wsp_[0-9A-Z]+$")
    if not isinstance(session_id, str) or not re.match(r"^vbc_sess_[0-9A-Z]+$", session_id or ""):
        return _err("VALIDATION_ERROR", "session_id must match ^vbc_sess_[0-9A-Z]+$")
    if not isinstance(input_text, str) or input_text.strip() == "":
        return _err("VALIDATION_ERROR", "input_text must be a non-empty string")
    norm_tags = _norm_tags(tags)
    if norm_tags is None:
        return _err("VALIDATION_ERROR", "tags must be an array of strings when provided")

    workspaces = _load("workspaces.json")
    sessions = _load("sessions.json")
    tool_runs = _load("tool_runs.json")
    learned_patterns = _load("learned_patterns.json")

    wsp = next((w for w in workspaces if w.get("id") == workspace_id and w.get("status") == "active"), None)
    if not wsp:
        return _err("UNAUTHORIZED", "Not authorized for workspace, or workspace not active")

    sess = next((s for s in sessions if s.get("id") == session_id and s.get("workspace_id") == workspace_id), None)
    if not sess:
        return _err("NOT_FOUND", "Session not found in workspace")
    if sess.get("status") == "deleted":
        return _err("INVALID_TRANSITION", "Cannot run tools on a deleted session")

    # create tool run
    now = _now()
    run_id = _make_id("vbc_run_")
    req_payload = {"workspace_id": workspace_id, "session_id": session_id, "input_text": input_text}
    if tags is not None:
        req_payload["tags"] = tags

    run_row = {
        "id": run_id,
        "workspace_id": workspace_id,
        "session_id": session_id,
        "tool_name": "vibe_learn",
        "status": "running",
        "request_payload": req_payload,
        "input_text": input_text,
        "response_payload": None,
        "output_text": None,
        "error_code": None,
        "error_message": None,
        "duration_ms": None,
        "tokens_in": _estimate_tokens(input_text),
        "tokens_out": None,
        "created_at": now,
        "updated_at": now,
        "started_at": now,
        "finished_at": None,
    }
    tool_runs.append(run_row)

    # Extract a candidate pattern: try to parse "problem:" / "solution:" blocks, else heuristic
    txt = input_text.strip()
    low = txt.lower()

    def _extract_field(label):
        m = re.search(rf"(?im)^\s*{re.escape(label)}\s*:\s*(.+?)\s*$", txt)
        return m.group(1).strip() if m else None

    title = _extract_field("title")
    problem = _extract_field("problem")
    solution = _extract_field("solution")

    if not problem:
        # heuristic problem sentence
        parts = re.split(r"[\.!\?]\s+", txt)
        problem = parts[0].strip() if parts and parts[0].strip() else "Unspecified recurring issue"
    if not solution:
        # heuristic solution based on common phrases
        if "missing" in low and "validation" in low:
            solution = "Add input validation and clear error messages; add tests for invalid inputs."
        elif "race" in low or "concurrency" in low:
            solution = "Add proper locking/transaction boundaries; make operations idempotent where possible."
        elif "auth" in low or "unauthor" in low:
            solution = "Ensure correct authentication/authorization checks and use least-privilege access."
        else:
            solution = "Document the fix and add a regression test to prevent recurrence."
    if not title:
        # compact title
        title = re.sub(r"[^A-Za-z0-9\s\-\_]", "", problem).strip()
        title = re.sub(r"\s+", " ", title)[:64] or "Learned pattern"

    # pattern_key: stable dedupe key by normalized hash of problem+solution stem
    key_base = (re.sub(r"\s+", " ", (problem + "|" + solution).strip().lower()))[:4000]
    pattern_key = hashlib.sha1(key_base.encode("utf-8")).hexdigest()[:16]

    # enforce non-empty fields
    if not isinstance(title, str) or title.strip() == "":
        # should not happen due to fallback
        title = "Learned pattern"
    if not isinstance(problem, str) or problem.strip() == "":
        problem = "Unspecified recurring issue"
    if not isinstance(solution, str) or solution.strip() == "":
        solution = "Add documentation and tests to prevent recurrence."

    now_dt = _now_dt()
    now_iso = now_dt.isoformat()

    # create or update within workspace unique(workspace_id, pattern_key)
    existing = next(
        (p for p in learned_patterns if p.get("workspace_id") == workspace_id and p.get("pattern_key") == pattern_key and p.get("status") != "deleted"),
        None,
    )

    changed = {"created": False, "updated": False}
    pattern_row = None
    if existing:
        # update: increment evidence_count, last_seen_at, tags union, updated_by_run_id
        try:
            ev = int(existing.get("evidence_count", 0))
        except Exception:
            ev = 0
        existing["evidence_count"] = max(0, ev + 1)
        # keep first_seen_at, update last_seen_at >= first_seen_at
        fs = existing.get("first_seen_at")
        fs_dt = None
        if isinstance(fs, str):
            try:
                fs_dt = datetime.datetime.fromisoformat(fs[:-1] + "+00:00") if fs.endswith("Z") else datetime.datetime.fromisoformat(fs)
            except Exception:
                fs_dt = None
        if fs_dt and now_dt < fs_dt:
            existing["last_seen_at"] = fs  # clamp
        else:
            existing["last_seen_at"] = now_iso

        # optionally refresh title/problem/solution if input provides explicit fields
        if _extract_field("problem") or _extract_field("solution") or _extract_field("title"):
            existing["title"] = title
            existing["problem"] = problem
            existing["solution"] = solution

        # tags: union, preserve existing order then add new
        ex_tags = existing.get("tags")
        if not isinstance(ex_tags, list):
            ex_tags = []
        seen = set([str(t).lower() for t in ex_tags if isinstance(t, str)])
        for t in norm_tags:
            if t.lower() not in seen:
                ex_tags.append(t)
                seen.add(t.lower())
        existing["tags"] = ex_tags[:50]

        existing["updated_by_run_id"] = run_id
        existing["updated_at"] = now_iso
        changed["updated"] = True
        pattern_row = existing
    else:
        pat_id = _make_id("vbc_pat_")
        pattern_row = {
            "id": pat_id,
            "workspace_id": workspace_id,
            "status": "active",
            "pattern_key": pattern_key,
            "title": title,
            "problem": problem,
            "solution": solution,
            "tags": norm_tags,
            "evidence_count": 1,
            "first_seen_at": now_iso,
            "last_seen_at": now_iso,
            "created_by_run_id": run_id,
            "updated_by_run_id": run_id,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        learned_patterns.append(pattern_row)
        changed["created"] = True

    # finalize run
    finished = _now()
    run_row["status"] = "succeeded"
    run_row["response_payload"] = {"pattern_id": pattern_row.get("id"), "pattern_key": pattern_key, **changed}
