    run_row["finished_at"] = finished
    run_row["updated_at"] = finished
    run_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
    run_row["tokens_out"] = _estimate_tokens(json.dumps(run_row["response_payload"], ensure_ascii=False))

    _save("tool_runs.json", tool_runs)
    _save("learned_patterns.json", learned_patterns)

    return {"tool_run": run_row, "learned_pattern": pattern_row}

def list_sessions(workspace_id, status=None, q=None, opened_after=None, opened_before=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0363000" if __import__("os").path.isdir("./environment_mix/0363000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _dt_key(val):
        d = _parse_dt(val) if isinstance(val, str) else None
        if d is None:
            return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        if d.tzinfo is None:
            d = d.replace(tzinfo=datetime.timezone.utc)
        return d

    # validation
    if not isinstance(workspace_id, str) or not re.match(r"^vbc_wsp_[0-9A-Z]+$", workspace_id or ""):
        return _err("VALIDATION_ERROR", "workspace_id must match ^vbc_wsp_[0-9A-Z]+$")

    if status is not None:
        if not isinstance(status, str) or status not in ("open", "archived", "deleted"):
            return _err("VALIDATION_ERROR", "status must be one of: open, archived, deleted")

    if q is not None and not isinstance(q, str):
        return _err("VALIDATION_ERROR", "q must be a string when provided")

    oa = _parse_dt(opened_after) if opened_after is not None else None
    if opened_after is not None and oa is None:
        return _err("VALIDATION_ERROR", "opened_after must be an RFC3339 date-time string")

    ob = _parse_dt(opened_before) if opened_before is not None else None
    if opened_before is not None and ob is None:
        return _err("VALIDATION_ERROR", "opened_before must be an RFC3339 date-time string")

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")

    if sort is None:
        sort = "updated_at"
    if sort not in ("created_at", "updated_at", "opened_at"):
        return _err("VALIDATION_ERROR", "sort must be one of: created_at, updated_at, opened_at")

    if order is None:
        order = "desc"
    if order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "order must be one of: asc, desc")

    # load + auth (ambient)
    workspaces = _load("workspaces.json")
    sessions = _load("sessions.json")

    wsp = next((w for w in workspaces if w.get("id") == workspace_id and w.get("status") == "active"), None)
    if not wsp:
        return _err("UNAUTHORIZED", "Not authorized for workspace, or workspace not active")

    # apply filters
    rows = [s for s in sessions if s.get("workspace_id") == workspace_id]
    if status is not None:
        rows = [s for s in rows if s.get("status") == status]
    if q is not None and q.strip() != "":
        qq = q.lower()
        rows = [s for s in rows if qq in ((s.get("title") or "").lower())]
    if oa is not None:
        rows = [s for s in rows if _dt_key(s.get("opened_at")) >= (oa if oa.tzinfo else oa.replace(tzinfo=datetime.timezone.utc))]
    if ob is not None:
        rows = [s for s in rows if _dt_key(s.get("opened_at")) <= (ob if ob.tzinfo else ob.replace(tzinfo=datetime.timezone.utc))]

    # sort stable by (sort_field, id)
    reverse = (order == "desc")

    def _sort_key(s):
        return (_dt_key(s.get(sort)), str(s.get("id") or ""))

    rows.sort(key=_sort_key, reverse=reverse)

    # cursor: base64 json {"v": <sort_value>, "id": <id>}
    start_idx = 0
    next_cursor = None
    if cursor is not None:
        if not isinstance(cursor, str) or cursor.strip() == "":
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            c = json.loads(raw)
        except Exception:
            return _err("VALIDATION_ERROR", "cursor is invalid")
        cv = c.get("v")
        cid = c.get("id")
        # find first row after cursor in the sorted order
        for i, s in enumerate(rows):
            if str(s.get("id") or "") == str(cid) and (s.get(sort) == cv):
                start_idx = i + 1
                break

    page = rows[start_idx:start_idx + limit]
    has_more = (start_idx + limit) < len(rows)
    if has_more and page:
        last = page[-1]
        payload = {"v": last.get(sort), "id": last.get("id")}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, ensure_ascii=False).encode("utf-8")).decode("utf-8").rstrip("=")

    return {
        "sessions": page,
        "meta": {
            "total": len(rows),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort,
            "order": order,
        },
    }

