            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_session"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    used_credential = None

    def _log(status_str, error_code=None):
        latency = int((time.time() - t0) * 1000)
        req_logs = _load("request_logs.json")
        if not isinstance(req_logs, list):
            req_logs = []
        req_logs.append({
            "id": "vbc_req_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("="),
            "endpoint": endpoint,
            "workspace_id": workspace_id if isinstance(workspace_id, str) else None,
            "credential": used_credential,
            "status": status_str,
            "error_code": error_code,
            "latency_ms": latency,
            "ts": now,
        })
        _save("request_logs.json", req_logs)

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                dt = datetime.datetime.fromisoformat(s2)
                return dt.replace(tzinfo=None)
            return datetime.datetime.fromisoformat(s.replace("Z", ""))
        except Exception:
            return None

    try:
        if not isinstance(workspace_id, str) or not re.match(r"^vbc_wsp_[0-9A-Z]+$", workspace_id):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "workspace_id is invalid.", field="workspace_id")
        if not isinstance(session_id, str) or not re.match(r"^vbc_sess_[0-9A-Z]+$", session_id):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "session_id is invalid.", field="session_id")
        if title is not None:
            if not isinstance(title, str) or len(title) < 1 or len(title) > 200:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "title must be a non-empty string up to 200 chars.", field="title")
        if context is not None and not isinstance(context, dict):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "context must be an object.", field="context")
        if status is not None:
            if not isinstance(status, str) or status not in ("open", "archived", "deleted"):
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "status must be one of open, archived, deleted.", field="status")
        if closed_at is not None:
            if _parse_dt(closed_at) is None:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "closed_at must be an ISO-8601 date-time string.", field="closed_at")

        workspaces = _load("workspaces.json")
        wsp = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
        if not wsp:
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)
        if wsp.get("status") != "active":
            _log("error", "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Workspace is not active; cannot update session.", workspace_id=workspace_id)

        sessions = _load("sessions.json")
        if not isinstance(sessions, list):
            sessions = []
        idx = None
        for i, s in enumerate(sessions):
            if isinstance(s, dict) and s.get("id") == session_id and s.get("workspace_id") == workspace_id:
                idx = i
                break
        if idx is None:
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Session not found in workspace.", workspace_id=workspace_id, session_id=session_id)

        sess = sessions[idx]
        old_status = sess.get("status")

        transitions = {
            "open": set(["archived", "deleted"]),
            "archived": set(["open", "deleted"]),
            "deleted": set([]),
        }

        # lifecycle/status update
        if status is not None and status != old_status:
            if old_status not in transitions or status not in transitions[old_status]:
                _log("error", "INVALID_TRANSITION")
                return _err("INVALID_TRANSITION", "Illegal session status transition.", from_status=old_status, to_status=status)
            sess["status"] = status
            if status in ("archived", "deleted"):
                sess["closed_at"] = closed_at if closed_at is not None else now
            elif status == "open":
                sess["closed_at"] = None

        # closed_at consistency if provided without status change
        if closed_at is not None and (status is None or status == old_status):
            if old_status not in ("archived", "deleted"):
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "closed_at can only be set when status is archived or deleted.", field="closed_at")
            sess["closed_at"] = closed_at

        if title is not None:
            sess["title"] = title
        if context is not None:
            sess["context"] = context

        sess["updated_at"] = now
        sessions[idx] = sess

        # Cascade delete if status -> deleted
        if old_status != "deleted" and sess.get("status") == "deleted":
            tool_runs = _load("tool_runs.json")
            if not isinstance(tool_runs, list):
                tool_runs = []
            distilled = _load("distilled_plans.json")
            if not isinstance(distilled, list):
                distilled = []
            learned = _load("learned_patterns.json")
            if not isinstance(learned, list):
                learned = []

            # delete tool_runs for this session (cascade)
            deleted_run_ids = set()
            kept_runs = []
            for r in tool_runs:
                if isinstance(r, dict) and r.get("workspace_id") == workspace_id and r.get("session_id") == session_id:
                    deleted_run_ids.add(r.get("id"))
                else:
                    kept_runs.append(r)

            # delete distilled plans for this session (cascade)
            kept_plans = []
            for p in distilled:
                if isinstance(p, dict) and p.get("workspace_id") == workspace_id and p.get("session_id") == session_id:
                    continue
                kept_plans.append(p)

            # set null learned_patterns references for deleted tool_runs (FK set null)
            if deleted_run_ids:
                for lp in learned:
                    if not isinstance(lp, dict) or lp.get("workspace_id") != workspace_id:
                        continue
                    if lp.get("created_by_run_id") in deleted_run_ids:
                        lp["created_by_run_id"] = None
                        lp["updated_at"] = now
                    if lp.get("updated_by_run_id") in deleted_run_ids:
                        lp["updated_by_run_id"] = None
                        lp["updated_at"] = now

            _save("tool_runs.json", kept_runs)
            _save("distilled_plans.json", kept_plans)
            _save("learned_patterns.json", learned)

        _save("sessions.json", sessions)

        _log("ok", None)
        return {"session": sess}
    except Exception as e:
        _log("error", "INTERNAL_ERROR")
        return _err("VALIDATION_ERROR", "Unexpected error.", details=str(e))

