    def _parse_dt(s, field_name):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field_name} must be an RFC3339 datetime string.", field=field_name)
        try:
            # accept "Z" and offsets; treat naive as UTC
            if s.endswith("Z"):
                dt = datetime.datetime.fromisoformat(s[:-1])
            else:
                dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt, None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field_name} is invalid.", field=field_name)

    def _dt_from_row(v):
        if not isinstance(v, str) or not v:
            return None
        try:
            if v.endswith("Z"):
                dt = datetime.datetime.fromisoformat(v[:-1])
            else:
                dt = datetime.datetime.fromisoformat(v)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt
        except Exception:
            return None

    def _decode_cursor(cur):
        # Opaque cursor; accept any string. If malformed, treat as "start from beginning"
        if cur is None:
            return None
        if not isinstance(cur, str) or cur == "":
            return None
        try:
            pad = "=" * (-len(cur) % 4)
            raw = base64.urlsafe_b64decode(cur + pad).decode("utf-8")
            obj = json.loads(raw)
            if isinstance(obj, dict):
                return obj
            return None
        except Exception:
            return None

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    # ---------- validation ----------
    if not isinstance(workspace_id, str) or not re.match(r"^vbc_wsp_[0-9A-Z]+$", workspace_id):
