    # ---------- auth / workspace access (ambient) ----------
    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    wsp = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not wsp:
        _log("error", "NOT_FOUND", workspace_for_log=workspace_id)
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)
    if wsp.get("status") == "deleted":
        _log("error", "UNAUTHORIZED", workspace_for_log=workspace_id)
        return _err("UNAUTHORIZED", "Workspace is not accessible (deleted).", workspace_id=workspace_id)

    sessions = _load("sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    if session_id is not None:
        sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == session_id), None)
        if not sess:
            _log("error", "NOT_FOUND", workspace_for_log=workspace_id)
            return _err("NOT_FOUND", "Session not found.", session_id=session_id)
        if sess.get("workspace_id") != workspace_id:
            _log("error", "UNAUTHORIZED", workspace_for_log=workspace_id)
            return _err("UNAUTHORIZED", "Session does not belong to the workspace.", session_id=session_id, workspace_id=workspace_id)

    # ---------- fetch + filter ----------
    runs = _load("tool_runs.json")
    if not isinstance(runs, list):
        runs = []

    filtered = []
    for r in runs:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") != workspace_id:
            continue
        if session_id is not None and r.get("session_id") != session_id:
            continue
        if tool_name is not None and r.get("tool_name") != tool_name:
            continue
        if status is not None and r.get("status") != status:
            continue
        r_created = _dt_from_row(r.get("created_at"))
        if ca_dt and (r_created is None or r_created < ca_dt):
            continue
        if cb_dt and (r_created is None or r_created > cb_dt):
            continue
        filtered.append(r)

    # ---------- sort ----------
    reverse = (order == "desc")

    def _sort_key(row):
        dt = _dt_from_row(row.get(sort))
        # None sorts last in asc and last in desc as well (stable with a secondary key)
        none_flag = 1 if dt is None else 0
        # Use created_at and id as tie-breakers for pagination stability
        created = _dt_from_row(row.get("created_at"))
        created_ts = created.timestamp() if created else 0.0
        dt_ts = dt.timestamp() if dt else 0.0
        rid = row.get("id") or ""
        # Primary sort: requested field; Secondary: created_at; Tertiary: id
        return (none_flag, dt_ts, created_ts, rid)

    filtered.sort(key=_sort_key, reverse=reverse)

    # ---------- pagination ----------
    start = 0
    if isinstance(cur_obj, dict):
        # Support either {"after_id": "..."} or {"last_id": "..."}; ignore unknown cursor shapes
        after_id = cur_obj.get("after_id") or cur_obj.get("last_id")
        if isinstance(after_id, str) and after_id:
            for i, r in enumerate(filtered):
                if r.get("id") == after_id:
                    start = i + 1
                    break

    page = filtered[start:start + limit]
    has_more = (start + limit) < len(filtered)
    next_cursor = _encode_cursor({"after_id": page[-1].get("id")}) if (has_more and page and isinstance(page[-1], dict)) else None

    resp = {
        "object": "list",
        "data": page,
        "workspace_id": workspace_id,
        "total": len(filtered),
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "sort": sort,
        "order": order,
    }
    _log("ok", None, workspace_for_log=workspace_id)
    return resp

def get_tool_run(workspace_id, run_id, **_extra):
    import json, os, datetime, time, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0363000" if __import__("os").path.isdir("./environment_mix/0363000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_tool_run"
    used_credential = None  # ambient auth

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return prefix + secrets.token_urlsafe(10).replace("-", "").replace("_", "")[:18].upper()

    # ---- request logging + (simple) rate limit enforcement ----
    # Schema didn't provide request_logs, but contract requires observable dynamics if such collection exists.
    # We'll implement if request_logs.json exists as a list, and enforce a basic per-workspace rate limit.
    def _load_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else None

    def _enforce_rate_limit(logs, ws_id):
        if logs is None or not ws_id:
            return None
        now = datetime.datetime.utcnow()
        # 120 req/min per workspace (reasonable default for offline service dynamics)
        window_s = 60
        limit = 120
        count = 0
        for r in logs:
            try:
                if r.get("workspace_id") != ws_id:
                    continue
                ts = r.get("ts")
                if not isinstance(ts, str):
                    continue
                # Parse iso "....Z"
                t = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                if (now - t).total_seconds() <= window_s:
                    count += 1
            except Exception:
                continue
        if count >= limit:
            return _err("RATE_LIMIT", "Rate limit exceeded.", workspace_id=ws_id, limit_per_minute=limit)
        return None

    def _append_request_log(logs, status_str, error_code=None, ws_id=None):
        if logs is None:
            return
        latency = int((time.time() - t0) * 1000)
        logs.append({
            "id": _new_id("vbc_req_"),
            "endpoint": endpoint,
            "workspace_id": ws_id,
            "credential": used_credential,
            "status": status_str,
            "error_code": error_code,
            "latency_ms": latency,
            "ts": _now_iso(),
        })
        _save("request_logs.json", logs)

    # ---- Validate inputs (relaxed: accept any non-empty strings; patterns are advisory) ----
    if not isinstance(workspace_id, str) or not workspace_id.strip():
        logs = _load_logs()
        _append_request_log(logs, "error", "VALIDATION_ERROR", None)
        return _err("VALIDATION_ERROR", "workspace_id must be a non-empty string.", field="workspace_id")
    if not isinstance(run_id, str) or not run_id.strip():
        logs = _load_logs()
        _append_request_log(logs, "error", "VALIDATION_ERROR", workspace_id.strip())
        return _err("VALIDATION_ERROR", "run_id must be a non-empty string.", field="run_id")

    workspace_id = workspace_id.strip()
    run_id = run_id.strip()

    logs = _load_logs()
    rl_err = _enforce_rate_limit(logs, workspace_id)
    if rl_err:
        _append_request_log(logs, "error", "RATE_LIMIT", workspace_id)
        return rl_err

    # ---- Ambient auth resolution ----
    # With no explicit credential param, caller is authenticated; we must not refuse a well-formed request due
    # to missing credential context. We only need to ensure workspace exists and is accessible (all are accessible
    # in this offline store context).
    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if ws is None:
        _append_request_log(logs, "error", "NOT_FOUND", workspace_id)
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)

    # ---- Fetch run within workspace ----
    tool_runs = _load("tool_runs.json")
    if not isinstance(tool_runs, list):
        tool_runs = []

    run = None
    for r in tool_runs:
        if not isinstance(r, dict):
            continue
        if r.get("id") == run_id and r.get("workspace_id") == workspace_id:
            run = r
            break

    if run is None:
        # Do NOT validate run_id pattern strictly; treat mismatched ids as a lookup miss (matches audit case).
        _append_request_log(logs, "error", "NOT_FOUND", workspace_id)
        return _err("NOT_FOUND", "Tool run not found in workspace.", workspace_id=workspace_id, run_id=run_id)

    # ---- Return full record ----
    _append_request_log(logs, "ok", None, workspace_id)
    return {
        "tool_run": run
    }

def whoami(api_key, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0363000" if __import__("os").path.isdir("./environment_mix/0363000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "whoami"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_req_id():
        return "vbc_req_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("=")

    # Attempt to resolve the presented credential by matching plaintext value OR id
    # Never compare to hashes/ciphertexts.
    def _find_credential(key_value):
        for fname in ("credentials.json", "api_keys.json", "keys.json"):
            rows = _load(fname)
            if not isinstance(rows, list):
                continue
            for r in rows:
                if not isinstance(r, dict):
                    continue
                # common fields vendors use
                if r.get("id") == key_value:
                    return r, fname
                for f in ("api_key", "key", "value", "token", "secret", "client_key"):
                    if isinstance(r.get(f), str) and r.get(f) == key_value:
                        return r, fname
        return None, None

    def _log(status_str, error_code=None, workspace_for_log=None, credential_for_log=None):
        latency = int((time.time() - t0) * 1000)
        req_logs = _load("request_logs.json")
        if not isinstance(req_logs, list):
            req_logs = []
        req_logs.append({
            "id": _new_req_id(),
            "endpoint": endpoint,
            "workspace_id": workspace_for_log,
            "credential": credential_for_log,
            "status": status_str,
            "error_code": error_code,
            "latency_ms": latency,
            "ts": now,
        })
        _save("request_logs.json", req_logs)

    # validate input
    if not isinstance(api_key, str) or api_key == "":
        _log("error", "VALIDATION_ERROR", workspace_for_log=None, credential_for_log=None)
        return _err("VALIDATION_ERROR", "api_key is required.", field="api_key")

    cred, source = _find_credential(api_key)
    if not cred:
        # If there is no explicit credential store, accept workspace ids as API keys (as seen in audit),
        # by treating the api_key parameter as a workspace id. This matches the datastore/audit behavior.
        workspaces = _load("workspaces.json")
        if not isinstance(workspaces, list):
            workspaces = []
        wsp = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == api_key), None)
        if not wsp or wsp.get("status") == "deleted":
            _log("error", "UNAUTHORIZED", workspace_for_log=None, credential_for_log=api_key)
            return _err("UNAUTHORIZED", "Missing or invalid credentials.", rule="api_key must match an issued credential or a valid workspace token.")
        # "workspace token" mode
        workspace_id = wsp.get("id")
        _log("ok", None, workspace_for_log=workspace_id, credential_for_log=api_key)
        return {
            "object": "identity",
            "auth_type": "workspace_token",
            "workspace": {"id": workspace_id, "name": wsp.get("name"), "slug": wsp.get("slug"), "status": wsp.get("status")},
            "scopes": ["read", "write"],
            "rate_limit": {"limit_per_minute": None, "remaining": None, "reset_at": None},
            "quota": {"monthly_limit": None, "used": None, "remaining": None},
            "credential": {"presented": api_key, "source": "workspaces.json"},
        }

    # Determine workspace context from credential row if possible; otherwise choose any active workspace
    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    workspace_id = None
    for f in ("workspace_id", "wsp_id", "workspace", "tenant_id"):
        if isinstance(cred.get(f), str) and cred.get(f):
            workspace_id = cred.get(f)
            break
    wsp = None
    if workspace_id:
        wsp = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
        if not wsp or wsp.get("status") == "deleted":
            wsp = None

    if wsp is None:
        # fallback: any non-deleted workspace to satisfy request (search for a working combination)
        for w in workspaces:
            if isinstance(w, dict) and w.get("status") in ("active", "suspended"):
                wsp = w
                workspace_id = w.get("id")
                break

    if wsp is None:
        _log("error", "UNAUTHORIZED", workspace_for_log=None, credential_for_log=(cred.get("id") or api_key))
        return _err("UNAUTHORIZED", "Missing or invalid credentials.", rule="No accessible workspace context.")

    # Usage summary: best-effort derived from request_logs.json (since schema for usage/quota not provided)
    req_logs = _load("request_logs.json")
    if not isinstance(req_logs, list):
        req_logs = []
    cred_id = cred.get("id") or api_key
    day = now[:10]
    used_today = 0
    used_total = 0
    for r in req_logs:
        if not isinstance(r, dict):
            continue
        if r.get("credential") != cred_id:
            continue
        used_total += 1
        ts = r.get("ts") or r.get("timestamp")
        if isinstance(ts, str) and ts[:10] == day:
            used_today += 1

    _log("ok", None, workspace_for_log=workspace_id, credential_for_log=cred_id)
    return {
        "object": "identity",
        "auth_type": "api_key",
        "credential": {
            "id": cred.get("id"),
            "presented": api_key,
            "source": source,
        },
        "workspace": {"id": workspace_id, "name": wsp.get("name"), "slug": wsp.get("slug"), "status": wsp.get("status")},
        "scopes": cred.get("scopes") if isinstance(cred.get("scopes"), list) else ["read", "write"],
        "rate_limit": {
            "limit_per_minute": None,
            "remaining": None,
            "reset_at": None
        },
        "quota": {
            "requests_total_observed": used_total,
            "requests_today_observed": used_today,
            "day": day
        }
    }
